import{_ as n,l as o,o as e,c as l,v as r,p as s,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"回文自动机","description":"","frontmatter":{"title":"回文自动机","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/palindromic-tree.md","filePath":"cs/palindromic-tree.md","lastUpdated":1789023840000}'),h={name:"cs/palindromic-tree.md"};function E(m,a,u,f,_,A){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="回文自动机" tabindex="-1">回文自动机 <a class="header-anchor" href="#回文自动机" aria-label="Permalink to &quot;回文自动机&quot;">​</a></h1><div class="epigraph"><p>每个本质不同回文一个节点；失配跳到当前回文的最长真回文后缀，加字符只在两端对称时生长。</p><footer>—— 据 Rubinchik and Shur, EERTREE: An Efficient Data Structure for Processing Palindromes in Strings, 2018（Eur. J. Comb. / 会议前置版本）；Manacher 线性回文半径整理</footer></div><p><a href="/cs/suffix-automaton">上一课</a> 的状态按结束集合走，不专门压缩回文。<a href="/cs/kmp">KMP</a> 的 \\(\\pi\\) 也不是回文。Manacher 给出每个中心的最长半径，但不索引「本质不同回文」。本课不克隆 SAM。缺口是回文树（eertree / palindromic automaton）：本质不同回文 \\(O(n)\\) 个。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>串的本质不同回文个数 \\(\\le n+1\\)（奇偶各一棵树的经典界）。节点 = 一个回文串；转移 \\(c\\) 表示两侧加 \\(c\\)。fail 指向最长真回文后缀。在线加字符：从 last 沿 fail 找到能加该字符的回文，没有则新建。缺口是<strong>把回文集合做成自动机</strong>，从而计数、最长回文、回文分割 DP 的转移可沿节点走。</p><p><span class="marginnote">Manacher 1975 线性最长回文。eertree 由 Rubinchik–Shur 系统化（会议 CPM 等，期刊 2018 左右）。本课不发明 arXiv 号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两棵根：偶空与奇「虚」。维护 last。加字符与 SAM 同风格但谓词是回文可扩展。每个节点 <code>len</code>。出现次数可挂 fail 树求和。</p>',8)),(e(),s(p,null,{default:t(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAL%5B%22%E6%9C%AC%E8%B4%A8%E5%9B%9E%E6%96%87%22%5D%20--%3E%20NODE%5B%22%E6%A0%91%E8%8A%82%E7%82%B9%22%5D%0A%20%20NODE%20--%3E%20CH%5B%22%E4%B8%A4%E4%BE%A7%E5%8A%A0%E5%AD%97%E7%AC%A6%22%5D%0A%20%20NODE%20--%3E%20FAIL%5B%22%E6%9C%80%E9%95%BF%E5%9B%9E%E6%96%87%E5%90%8E%E7%BC%80%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与 Manacher：Manacher 要每个中心的最长；eertree 要集合与转移。两者都线性，问题不同。与 SAM：回文约束更强，节点更少类。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>新建节点时 fail 必须存在且唯一最长。实现注意奇偶长度。不要用中心枚举 $+ $ 哈希当本课的结构定义——那是后课哈希的应用。</p><p>字符串索引课序接下来从确定性自动机转到期望相等：滚动哈希。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把回文树与 SAM 联合结构写完。二维回文不是一维自动机。哈希冲突合同与本课无关。</p><p>后课默认：本质回文用 eertree 或 Manacher。要期望比较子串，用字符串哈希。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回文自动机：本质回文 \\(O(n)\\) 节点 + fail。</li><li>在线加字符沿 fail 扩展。</li><li>下一课滚动哈希，不保证零错误。</li><li>出处：Manacher；Rubinchik and Shur, eertree。</li></ul>',9))])}const b=n(h,[["render",E]]);export{P as __pageData,b as default};
